import json
with open('/app/resources/treasury_bulletin_2016_12.json', 'r') as f:
    data = json.load(f)

# Look for OCS or Outer Continental Shelf related data
def find_ocs(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'ocS' in str(k).lower() or 'outer' in str(k).lower() or 'continental' in str(k).lower() or 'shelf' in str(k).lower() or 'rent' in str(k).lower() or 'royalty' in str(k).lower():
                print(f'{path}{k}: {v}')
            find_ocs(v, f'{path}{k}.')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_ocs(item, f'{path}[{i}].')

find_ocs(data)
